// Config plugin: benchmark equalisation settings for the generated native projects (design §13.2). android/ and
// ios/ are generated by `npx expo prebuild` (CNG) and never edited by hand, so every change lives here.
//   Android: <profileable android:shell="true"/>, cleartext only for localhost / 127.0.0.1 / 10.0.2.2 (network
//            security config), androidx.profileinstaller, release signing with the local non-distribution key from
//            MB_KEYSTORE_PROPERTIES (storeFile, storePassword, keyAlias, keyPassword) when that file exists.
//   iOS:     Info.plist keys come from app.json `ios.infoPlist`.
const fs = require('fs');
const path = require('path');
const { withAndroidManifest, withAppBuildGradle, withDangerousMod } = require('expo/config-plugins');

const PROFILEINSTALLER = 'androidx.profileinstaller:profileinstaller:1.4.1';
const MARKER = '// mobilebench: equalisation (plugins/withMobileBench.js)';

const NETWORK_SECURITY_CONFIG = `<?xml version="1.0" encoding="utf-8"?>
<!-- Cleartext HTTP/WebSocket only for the local benchmark server (loopback and the emulator host alias). -->
<network-security-config>
  <domain-config cleartextTrafficPermitted="true">
    <domain includeSubdomains="false">localhost</domain>
    <domain includeSubdomains="false">127.0.0.1</domain>
    <domain includeSubdomains="false">10.0.2.2</domain>
  </domain-config>
</network-security-config>
`;

const GRADLE_APPENDIX = `
${MARKER}
dependencies {
    implementation("${PROFILEINSTALLER}")
}

def mbKeystoreProperties = System.getenv("MB_KEYSTORE_PROPERTIES")
if (mbKeystoreProperties != null && new File(mbKeystoreProperties).exists()) {
    def mbProps = new Properties()
    new File(mbKeystoreProperties).withInputStream { mbProps.load(it) }
    android.signingConfigs.create("mobilebench") {
        storeFile new File(mbProps["storeFile"])
        storePassword mbProps["storePassword"]
        keyAlias mbProps["keyAlias"]
        keyPassword mbProps["keyPassword"]
    }
    android.buildTypes.release.signingConfig android.signingConfigs.mobilebench
}
`;

function withMobileBenchManifest(config) {
  return withAndroidManifest(config, (cfg) => {
    const app = cfg.modResults.manifest.application[0];
    app.$['android:networkSecurityConfig'] = '@xml/mb_network_security_config';
    delete app.$['android:usesCleartextTraffic'];
    app.profileable = [{ $: { 'android:shell': 'true' } }];
    return cfg;
  });
}

function withMobileBenchNetworkConfig(config) {
  return withDangerousMod(config, [
    'android',
    async (cfg) => {
      const dir = path.join(cfg.modRequest.platformProjectRoot, 'app', 'src', 'main', 'res', 'xml');
      fs.mkdirSync(dir, { recursive: true });
      fs.writeFileSync(path.join(dir, 'mb_network_security_config.xml'), NETWORK_SECURITY_CONFIG);
      return cfg;
    },
  ]);
}

function withMobileBenchGradle(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== 'groovy') {
      throw new Error('withMobileBench: expected a Groovy app/build.gradle');
    }
    if (!cfg.modResults.contents.includes(MARKER)) {
      cfg.modResults.contents += GRADLE_APPENDIX;
    }
    return cfg;
  });
}

module.exports = function withMobileBench(config) {
  return withMobileBenchGradle(withMobileBenchNetworkConfig(withMobileBenchManifest(config)));
};
